const I18N_TEXT=new Map(I18N_ROWS.map(([en,ko,vi])=>[en,{ko,vi}]));
function isLanguage(code){return LANGUAGES.some(([c])=>c===code);}
function startingLanguage(){let saved=null;try{saved=localStorage.getItem(LANGUAGE_KEY);}catch(e){}if(isLanguage(saved))return saved;const browser=(navigator.language||'').slice(0,2).toLowerCase();return isLanguage(browser)?browser:'en';}
let currentLanguage=startingLanguage();
document.documentElement.lang=currentLanguage;

function translateExact(text){return I18N_TEXT.get(text)?.[currentLanguage]??text;}
function translateString(value){
  if(currentLanguage==='en')return value;
  const text=value.trim();
  if(!text||!/[A-Za-z]/.test(text))return value;
  let result=I18N_TEXT.get(text)?.[currentLanguage];
  if(result===undefined){
    for(const [pattern,ko,vi] of I18N_PATTERNS){
      const match=text.match(pattern);
      if(match){result=(currentLanguage==='ko'?ko:vi).replace(/\$(\d)/g,(_,n)=>translateExact(match[n]));break;}
    }
  }
  return result===undefined?value:value.replace(text,()=>result);
}
function translateElementAttributes(element){
  for(const name of I18N_ATTRIBUTES){
    const value=element.getAttribute(name);
    if(value){const next=translateString(value);if(next!==value)element.setAttribute(name,next);}
  }
}
function translateTextNode(node){
  const parent=node.parentElement;
  if(!parent||parent.closest(I18N_SKIP))return;
  const next=translateString(node.nodeValue);
  if(next===node.nodeValue)return;
  // Code reads option.value, so an option must keep its English value when its label changes.
  if(parent.tagName==='OPTION'&&!parent.hasAttribute('value'))parent.setAttribute('value',node.nodeValue.trim());
  node.nodeValue=next;
}
function translateTree(root){
  if(currentLanguage==='en')return;
  if(root.nodeType===Node.TEXT_NODE){translateTextNode(root);return;}
  if(root.nodeType!==Node.ELEMENT_NODE)return;
  translateElementAttributes(root);
  root.querySelectorAll('*').forEach(translateElementAttributes);
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  while(walker.nextNode())translateTextNode(walker.currentNode);
}
/* Runs before the browser paints, so English never flashes. A translated string matches nothing, so this settles at once. */
new MutationObserver(records=>{
  for(const record of records){
    if(record.type==='childList')record.addedNodes.forEach(translateTree);
    else if(record.type==='characterData')translateTree(record.target);
    else translateElementAttributes(record.target);
  }
}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:I18N_ATTRIBUTES});

function languageSwitcher(){return `<div class="lang-switch" role="group" aria-label="Language">${LANGUAGES.map(([code,label])=>`<button type="button" data-lang="${code}" aria-pressed="${code===currentLanguage}">${label}</button>`).join('')}</div>`;}
function setLanguage(code){
  currentLanguage=code;
  document.documentElement.lang=code;
  try{localStorage.setItem(LANGUAGE_KEY,code);}catch(e){}
  render();
  document.querySelector(`[data-lang="${code}"]`)?.focus();
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-lang]');if(button&&button.dataset.lang!==currentLanguage)setLanguage(button.dataset.lang);});
